python - <<'PY'
import nbformat, json, re
nb=nbformat.read('/results/FS-Filters-executed.ipynb', as_version=4)
for i,cell in enumerate(nb.cells):
    if cell.cell_type=='code':
        outs=cell.get('outputs',[])
        txt=''
        for o in outs:
            if o.output_type=='stream': txt+=o.get('text','')
            elif o.output_type in ('execute_result','display_data'):
                txt+=str(o.get('data',{}).get('text/plain',''))
            elif o.output_type=='error': txt+='\n'.join(o.get('traceback',[]))
        if txt.strip():
            if re.search(r'accuracy|I-Gain|gain|hybrid', txt, re.I):
                print('CELL',i)
                print(txt[:2000])
                print('---')
PY

